/bin/bash -lc "python3 - <<'PY'
import ast
import hashlib
import importlib.util
import itertools
import json
import math
from pathlib import Path
import subprocess

root=Path('/workspace')
p=json.loads((root/'proposal.json').read_text())
r=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001'],text=True))

def validate(value,schema,path):
    expected=schema.get('type')
    if expected:
        cls={'object':dict,'array':list,'string':str,'boolean':bool}[expected]
        assert isinstance(value,cls),(path,expected)
    if 'const' in schema:
        assert value==schema['const'],path
    if 'enum' in schema:
        assert value in schema['enum'],path
    if isinstance(value,dict):
        assert all(k in value for k in schema.get('required',[])),path
        props=schema.get('properties',{})
        if schema.get('additionalProperties') is False:
            assert set(value)<=set(props),(path,set(value)-set(props))
        for k,v in value.items():
            if k in props:
                validate(v,props[k],path+'.'+k)
    if isinstance(value,list):
        assert len(value)>=schema.get('minItems',0),path
        for i,x in enumerate(value):
            if 'items' in schema:
                validate(x,schema['items'],path+'[%d]'%i)
    if isinstance(value,str):
        assert len(value)>=schema.get('minLength',0),path
validate(p['study'],r['study_schema'],'study')
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert p['parent_trial'] in r['context']['allowed_observation_ids']
assert set(p['study']['evidence_refs'])<=set(r['context']['allowed_observation_ids'])
assert 1<=len(p['variants'])<=4
assert len({v['name'] for v in p['variants']})==len(p['variants'])
assert len({v['file'] for v in p['variants']})==len(p['variants'])
assert any(v['role']=='candidate' for v in p['variants'])

allowed_imports={'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib'}
ancestor=ast.parse((root/'history_g2_r0002_aligned_replay.py').read_text())
def methods(tree):
    model=next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name=='Model')
    return {n.name:n for n in model.body if isinstance(n,ast.FunctionDef)}
anc=methods(ancestor)
common_ast=None
for v in p['variants']:
    assert Path(v['file']).name==v['file'] and v['file'].endswith('.py')
    s=(root/v['file']).read_text()
    compile(s,str(root/v['file']),'exec')
    tree=ast.parse(s)
    config=next(ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
    assert config==v['config'],v['name']
    for n in ast.walk(tree):
        if isinstance(n,ast.Import):
            assert all(a.name.split('.')[0] in allowed_imports for a in n.names)
        if isinstance(n,ast.ImportFrom):
            assert n.module and n.module.split('.')[0] in allowed_imports
        if isinstance(n,ast.Call) and isinstance(n.func,ast.Name):
            assert n.func.id not in {'open','exec','eval','compile','__import__','input'}
    own=methods(tree)
    for name in ['_encode','_score','_weights']:
        assert ast.dump(own[name],include_attributes=False)==ast.dump(anc[name],include_attributes=False),(v['file'],name)
    # Parameter-creating assignments and classifier construction must be identical.
    def params(node):
        body=node.body
        start=next(i for i,n in enumerate(body) if isinstance(n,ast.Assign) and isinstance(n.targets[0],ast.Attribute) and n.targets[0].attr=='embeddings')
        return [ast.dump(n,include_attributes=False) for n in body[start:]]
    assert params(own['__init__'])==params(anc['__init__']),v['file']
    tree.body=[n for n in tree.body if not (isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))]
    normalized=ast.dump(tree,include_attributes=False)
    if common_ast is None:
        common_ast=normalized
    assert normalized==common_ast,'Variant code differs beyond CONFIG'
    sha=hashlib.sha256(s.encode()).hexdigest()
    v['note']+=' Source SHA256: '+sha+'. Syntax/import/interface and inherited parameter-construction checks passed locally; Torch execution deferred to host.'
    print(v['name'],v['file'],sha)

# Independent scalar reference: exhaustive short action multisets and fixed scores.
# This checks the mathematical prior/control, not execution of Torch kernels.
cases=0
for length in range(8):
    for labels in itertools.product(range(1,5),repeat=length):
        counts={a:labels.count(a) for a in set(labels)}
        shifted=labels[length//2:]+labels[:length//2]
        assert sorted(labels)==sorted(shifted)
        assert sorted([counts[a] for a in labels])==sorted([counts[a] for a in shifted])
        if labels:
            scores=[(i%3-1)*0.7 for i in range(length)]
            z=[math.exp(s)/counts[a] for s,a in zip(scores,labels)]
            weights=[x/sum(z) for x in z]
            # Equivalent hierarchical mixture: within-action softmax and log-mean-exp action prior.
            means={a:sum(math.exp(s) for s,b in zip(scores,labels) if b==a)/counts[a] for a in counts}
            domain_weights={a:v/sum(means.values()) for a,v in means.items()}
            for s,a,w in zip(scores,labels,weights):
                local_denom=sum(math.exp(t) for t,b in zip(scores,labels) if b==a)
                assert abs(w-domain_weights[a]*math.exp(s)/local_denom)<1e-12
            eq=[1/counts[a] for a in labels]
            eq=[x/sum(eq) for x in eq]
            for a in counts:
                assert abs(sum(w for b,w in zip(labels,eq) if b==a)-1/len(counts))<1e-12
            if len(counts)==1:
                base=[math.exp(s) for s in scores]
                base=[x/sum(base) for x in base]
                assert max(abs(x-y) for x,y in zip(weights,base))<1e-12
        cases+=1

for a in p['knowledge_assessments']:
    assert a['decision'] in {'used','considered','rejected','unresolved'}
    assert set(a['variant_names'])<={v['name'] for v in p['variants']}
retrieved=set(r['context']['latest_knowledge_usage']['retrieved_ids'])
assert retrieved<={a['knowledge_id'] for a in p['knowledge_assessments']}
(root/'proposal.json').write_text(json.dumps(p,indent=2)+'\\n')
print('Study schema, references, four standalone modules, CONFIG-only contrasts and parameter construction: PASS')
print('Independent scalar prior/hierarchical-equivalence/control identities:',cases,'cases PASS')
print('Torch installed:',importlib.util.find_spec('torch') is not None)
print('Training executed: no')
PY"

